#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sets up the sticker naming service on the PC that runs the picture model.
# What it leaves behind:
#   ~/.config/firestream-sticker-namer/env        the settings
#   ~/.config/firestream-sticker-namer/key.json   the service account's key
#   <this folder>/.venv                           the virtual environment
#   ~/.config/systemd/user/sticker-namer.service  the unit
# Nothing it writes is in the repository.

# ask_or KEY "Prompt" DEFAULT is ask, with DEFAULT for an empty answer on a first run.
ask_or() {
  local key="$1" prompt="$2" default="$3"
  if _existing "$key" >/dev/null; then
    ask "$key" "$prompt"
  else
    ask "$key" "$prompt [Enter for $default]"
  fi
  [[ -n "${!key}" ]] || printf -v "$key" '%s' "$default"
}

run_wizard() {

TOTAL_STAGES=7

local TOOL_DIR CONFIG_DIR KEY_DEST UNIT_DIR
TOOL_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CONFIG_DIR="$HOME/.config/firestream-sticker-namer"
KEY_DEST="$CONFIG_DIR/key.json"
UNIT_DIR="$HOME/.config/systemd/user"
ENV_FILE="$CONFIG_DIR/env"

banner "FireStream sticker naming service"

# The settings hold the path of a key. Nobody else on this PC reads the folder.
mkdir -p "$CONFIG_DIR"
chmod 700 "$CONFIG_DIR"

# ── 1. The virtual environment, and the tool's own tests ───────────────────
stage "Python: the virtual environment and the tests"
say "The service runs in its own Python environment, in $TOOL_DIR/.venv."
say "The tests run first. They use no key, no network and no graphics card."
if ! command -v python3 >/dev/null 2>&1; then
  warn "python3 is not installed. Install it, then run this wizard again."
  exit 1
fi
[[ -x "$TOOL_DIR/.venv/bin/python" ]] || python3 -m venv "$TOOL_DIR/.venv"
"$TOOL_DIR/.venv/bin/python" -m pip install --quiet --upgrade pip
"$TOOL_DIR/.venv/bin/python" -m pip install --quiet \
  -r "$TOOL_DIR/requirements.txt" -r "$TOOL_DIR/requirements-dev.txt"
if "$TOOL_DIR/.venv/bin/python" -m pytest -q "$TOOL_DIR"; then
  say "The tests pass."
else
  warn "A test failed. That is a fault in the tool, not in your setup."
  confirm "Go on anyway?" || exit 1
fi
pause

# ── 2. The Firebase project and its bucket ─────────────────────────────────
stage "Firebase: the project and its Storage bucket"
say "The service reads sticker files from the project's Storage bucket."
open_url "https://console.firebase.google.com/"
step "Open the project. Its id is in the address: console.firebase.google.com/project/<project id>."
note "It is also the value of project_id in app/google-services.json."
ask PROJECT_ID "Project id:"
[[ -n "$PROJECT_ID" ]] || { warn "No project id given."; exit 1; }
write_env PROJECT_ID "$PROJECT_ID"
open_url "https://console.firebase.google.com/project/$PROJECT_ID/storage"
step "The bucket's name is at the top of the Files tab, after gs://."
note "It ends in .firebasestorage.app or .appspot.com."
ask BUCKET "Bucket name, without gs://:"
BUCKET="${BUCKET#gs://}"
[[ -n "$BUCKET" ]] || { warn "No bucket given."; exit 1; }
write_env BUCKET "$BUCKET"

# ── 3. The service account and its key ─────────────────────────────────────
stage "Google Cloud: a service account that can read stickers and write names"
if [[ -f "$KEY_DEST" ]] && confirm "A key is already at $KEY_DEST. Keep it?"; then
  say "Keeping the key that is there."
else
  say "The service gets an account of its own, with two roles and nothing else."
  say "Do not use the Firebase console's 'Generate new private key': that key may do everything."
  open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create?project=$PROJECT_ID"
  step "Name the account sticker-namer. Click 'Create and continue'."
  step "Add the role 'Cloud Datastore User' (reads and writes Firestore documents)."
  step "Click 'Add another role' and add 'Storage Object Viewer' (reads Storage objects)."
  step "Click 'Done'. Skip the step that grants users access."
  pause "Press Enter when the account is in the list"
  step "Click the account sticker-namer@$PROJECT_ID.iam.gserviceaccount.com in the list."
  step "Open the tab 'Keys'. Click 'Add key', then 'Create new key', choose JSON, click 'Create'."
  step "The browser saves a file named like $PROJECT_ID-0123456789ab.json."
  note "The labels in the console may differ a little. If key creation is refused, an"
  note "organisation policy forbids service account keys (iam.disableServiceAccountKeyCreation)."
  local KEY_DOWNLOAD=""
  ask KEY_DOWNLOAD "Path of the downloaded key file:"
  KEY_DOWNLOAD="${KEY_DOWNLOAD/#\~/$HOME}"
  if [[ ! -f "$KEY_DOWNLOAD" ]]; then
    warn "There is no file at $KEY_DOWNLOAD. Run the wizard again when you have the key."
    exit 1
  fi
  say "The key moves to $KEY_DEST, readable by you only. No copy stays in the download folder."
  if confirm "Move $KEY_DOWNLOAD there?"; then
    mv "$KEY_DOWNLOAD" "$KEY_DEST"
  else
    warn "Without the key the service cannot start."
    exit 1
  fi
fi
chmod 600 "$KEY_DEST"
write_env KEY_FILE "$KEY_DEST"

# ── 4. The engine and the model ────────────────────────────────────────────
stage "The picture model"
say "The model runs on this PC. Ollama is the default engine."
say "For llama.cpp's server, answer 'openai' and give the server's address."
ask_or ENGINE "Engine, ollama or openai:" "ollama"
ENGINE="${ENGINE,,}"
if [[ "$ENGINE" != "ollama" && "$ENGINE" != "openai" ]]; then
  warn "The engine is '$ENGINE'. It must be ollama or openai. Run the wizard again."
  exit 1
fi
write_env ENGINE "$ENGINE"
if [[ "$ENGINE" == "ollama" ]]; then
  ask_or ENGINE_URL "Address of the engine:" "http://127.0.0.1:11434"
  ask_or MODEL "Model:" "gemma4:26b"
else
  ask_or ENGINE_URL "Address of the engine:" "http://127.0.0.1:8080"
  ask_or MODEL "Model, as the server names it:" "qwen"
fi
write_env ENGINE_URL "$ENGINE_URL"
write_env MODEL "$MODEL"
say "The service waits while the graphics card has less free memory than the model needs."
note "About 10000 for gemma4:12b. The 26b model fills a 16 GB card. 0 never waits."
ask_or MIN_FREE_VRAM_MB "Free graphics memory to wait for, in MiB:" "10000"
write_env MIN_FREE_VRAM_MB "$MIN_FREE_VRAM_MB"

# ── 5. The engine runs and holds the model ─────────────────────────────────
stage "The engine: running, with the model"
if [[ "$ENGINE" == "openai" ]]; then
  step "Start your server with the model and its picture part, so that it answers at $ENGINE_URL."
  pause "Press Enter when the server runs"
else
  if ! command -v ollama >/dev/null 2>&1; then
    warn "ollama is not installed. Install it from https://ollama.com/download, then run this wizard again."
    exit 1
  fi
  step "Ollama has to run all the time. On most systems: sudo systemctl enable --now ollama"
  pause "Press Enter when Ollama runs"
  if curl -fsS --max-time 5 "$ENGINE_URL/api/version" >/dev/null 2>&1; then
    say "Ollama answers at $ENGINE_URL."
  else
    warn "Ollama does not answer at $ENGINE_URL. The service will wait for it."
  fi
  if confirm "Download $MODEL now, if it is not here yet? It is many gigabytes."; then
    ollama pull "$MODEL" || warn "The download failed. Run by hand: ollama pull $MODEL"
  fi
fi

# ── 6. The unit ────────────────────────────────────────────────────────────
stage "systemd: the service starts with your session"
say "The unit goes to $UNIT_DIR/sticker-namer.service and starts now."
mkdir -p "$UNIT_DIR"
sed "s|@TOOL_DIR@|$TOOL_DIR|g" "$TOOL_DIR/sticker-namer.service" > "$UNIT_DIR/sticker-namer.service"
systemctl --user daemon-reload
systemctl --user enable sticker-namer
systemctl --user restart sticker-namer
sleep 3
if systemctl --user is-active --quiet sticker-namer; then
  say "The service runs."
else
  warn "The service does not run. Its last lines:"
  journalctl --user -u sticker-namer -n 15 --no-pager || true
  exit 1
fi
say "It stops when you log out, unless your user may run services without a session."
if confirm "Keep it running while you are logged out (loginctl enable-linger)?"; then
  loginctl enable-linger "$USER" || warn "That failed. Run by hand: loginctl enable-linger $USER"
fi

# ── 7. One sticker, end to end ─────────────────────────────────────────────
stage "One sticker named end to end"
say "The phone asks through Firestore, so the rules for stickerNames have to be deployed."
step "In the repository: firebase deploy --only firestore:rules"
note "Look at the 'Firestore rules' run on GitHub first. The rules tests run only there."
pause "Press Enter when the rules are deployed"
step "On the phone: Settings, Stickers. Switch 'Name my stickers automatically' on."
step "Leave the screen and open it again. Opening it fetches the answers."
note "Your library's first batch takes a few seconds per sticker."
pause "Press Enter after a minute or two"
journalctl --user -u sticker-namer -n 20 --no-pager || true
say "A line like '3f9a0c1b22d4 done in 6.7 s' is a named sticker."
step "On the phone: the tab 'All stickers', the filter 'Named automatically'."
if confirm "Does a sticker show a name there?"; then
  say "The service works."
else
  SKIPPED+=("No sticker was named. Read: journalctl --user -u sticker-namer -f, and tools/sticker-namer/README.md")
fi

finish
}

run_wizard "$@"; exit
